            state=R.values;seeds=after;++segment;result.segments=segment;result.times.push_back(time);result.segmentIds.push_back(static_cast<double>(segment));result.sides.push_back(1);result.values.insert(result.values.end(),state.begin(),state.end());result.derivatives.insert(result.derivatives.end(),fPlus.begin(),fPlus.end());result.sensitivities.insert(result.sensitivities.end(),seeds.begin(),seeds.end());require(retained(result)<=options.maximumBytes/sizeof(double),"Hybrid retained data exceeded max_bytes.");
