    const std::vector<double> final(result.trajectory.values.end()-static_cast<std::ptrdiff_t>(n),result.trajectory.values.end());
    native_functions::DerivativeRequest request;request.order=1;request.requestedThreads=1;request.active.resize(1+n+np);std::iota(request.active.begin(),request.active.end(),0);
