    auto nativeOptions=native;const auto charge=native.chargeOperations;nativeOptions.chargeOperations=[&](std::size_t count){if(std::chrono::duration<double>(Clock::now()-started).count()>options.solver.maximumWallSeconds)throw std::runtime_error("Hybrid adjoint global wall-time budget reached.");if(charge)charge(count);};
