            if(np)settings.parameterJacobian=[&](double time,const double* y,double* output){std::vector<double> input(y,y+n);input.insert(input.end(),parameters.begin(),parameters.end());input.push_back(time);native_functions::DerivativeRequest derivatives;derivatives.order=1;derivatives.requestedThreads=1;derivatives.active.resize(np);std::iota(derivatives.active.begin(),derivatives.active.end(),n);const auto value=rhs.evaluate(options.gamma,input,derivatives);std::copy(value.jacobian.begin(),value.jacobian.end(),output);};
