            RunningObjective runningEvaluator;if(running)runningEvaluator=[&](double time,const double*y,const double*,double*dy,double*dp){const auto point=callbackInput(time,std::vector<double>(y,y+n),parameters);if(!dy&&!dp){double value=0;running->evaluateValues(options.gamma,point,std::span<double>(&value,1));return value;}const auto derivatives=running->evaluate(options.gamma,point,request);if(dy)std::copy_n(derivatives.jacobian.begin()+1,n,dy);if(dp)std::copy_n(derivatives.jacobian.begin()+static_cast<std::ptrdiff_t>(1+n),np,dp);return derivatives.values[0];};
            const auto smooth=solveAdjoint(definition,options.gamma,state,parameters,linearObjective,settings,nativeOptions,runningEvaluator);result.replaySteps+=smooth.solution->stats.steps;result.backwardSteps+=smooth.backwardSteps;result.checkpoints+=smooth.checkpoints;result.runningCost+=smooth.runningCost;result.objective+=smooth.runningCost;finite(result.objective);
